"""
BUNSEN v0.1.0 - build hook.  Writes bunsen_pkg.vhd next to this file (pure python, system python3).
Heirloom from the video clips; still WIN_20231205_23_09_56 t0.5 (clip frame 15 at 0.5 s).

The patch (.heirloom_work/rb_bunsen/notes.md), in virtual 1080-line coordinates:
  F   = H(xc + (x - xc + D(y) w + oh) sl) + V(sgn(Y) (|Y| + E(x) w) sl + ov),  Y = y - 520, xc = 1006
        H, V: the two oscillator waveforms; D, E: the cross-modulation (warp); fitted to the still's contours
  u   = frac(F x rings) -> background palette / key palette (128 entries per family)
  key = the still's bat shape: per 4-line row, runs of |x - 1006| in [a0, a1), [b0, b1) and [c0, edge)

ROMs written (luma pre-scaled 16/13 for the output stage's 13/16, drawn luma capped ~768 after the scale):
  C_BU_PB   256 x 32  background palette (Ember 0..127, Blue 128..255) by u: Y10 << 20 | U10 << 10 | V10
  C_BU_PF   256 x 32  key palette (R = 255; the RTL lowers R below the fade notch)
  C_BU_H    512 x 16  H(4 i virtual px), Q8 bands (signed 12 bits)
  C_BU_V    512 x 16  V(4 j lines), j signed (two's complement index), Q8 bands
  C_BU_E    512 x 8   E(4 i virtual px), signed lines
  C_BU_RT   256 x 80  rows y = 4 r: a0 8 | a1 10 | b0 10 | b1 10 | c0 10 | D 8 (signed px) | tb 8 | bl 8 | br 8
                      (key runs, the field's per-line warp, the blue pools: top-right bowl half-width about
                      x 1545, bottom-left right edge, bottom-right left edge - 1792; 0 / 0 / 255 = none)
"""
import os

HERE = os.path.dirname(os.path.abspath(__file__))

# ---- measured / fitted tables (generated by .heirloom_work/rb_bunsen/mktables.py) ----
H_HEX = ""
V_HEX = ""
E_HEX = ""
RT_HEX = ""
FLAME = -26

# ---- palettes (RGB anchors along u, measured on the stills) ----
EMBER_BG = [(0.00, (55, 40, 50)), (0.05, (100, 40, 124)), (0.11, (140, 43, 205)), (0.18, (205, 45, 245)),
            (0.27, (246, 50, 248)), (0.40, (250, 82, 245)), (0.53, (244, 48, 248)), (0.63, (196, 41, 243)),
            (0.72, (242, 24, 243)), (0.84, (238, 40, 246)), (0.91, (185, 42, 236)), (0.955, (125, 40, 180))]
BLUE_BG = [(0.00, (8, 27, 11)), (0.06, (4, 10, 16)), (0.12, (0, 0, 76)), (0.20, (0, 0, 126)), (0.30, (0, 0, 197)),
           (0.40, (0, 0, 240)), (0.60, (2, 4, 250)), (0.78, (0, 0, 235)), (0.88, (0, 0, 166)), (0.95, (0, 6, 70))]
EMBER_KEY = (16, 116)     # key G from red (dark-line phase) to orange
BLUE_KEY = (64, 206)      # red-orange to yellow
POOL_EMBER = (10, 23, 254)
POOL_BLUE = (240, 50, 245)
OUTLINE = (165, 45, 0)


def rgb_to_hw10(r, g, b):
    y = 0.299 * r / 255 + 0.587 * g / 255 + 0.114 * b / 255
    cb = (b / 255 - y) / 1.772
    cr = (r / 255 - y) / 1.402
    return (int(round(64 + y * 876)), int(round(512 + cr * 896)), int(round(512 + cb * 896)))


def hw(rgb):
    y, u, v = rgb_to_hw10(*rgb)
    y = min(64 + int(round((768 - 64) * 16 / 13)), int(round(64 + (y - 64) * 16 / 13)))
    return y, max(0, min(1023, u)), max(0, min(1023, v))


def lerp_cyc(anchors, u):
    pos = [a[0] for a in anchors] + [anchors[0][0] + 1.0]
    col = [a[1] for a in anchors] + [anchors[0][1]]
    for k in range(len(pos) - 1):
        if pos[k] <= u < pos[k + 1]:
            f = (u - pos[k]) / (pos[k + 1] - pos[k])
            return tuple(col[k][j] * (1 - f) + col[k + 1][j] * f for j in range(3))
    return col[0]


def word(rgb):
    y, u, v = hw(rgb)
    return (y << 20) | (u << 10) | v


def palettes():
    pb, pf = [], []
    for anchors in (EMBER_BG, BLUE_BG):
        pb += [word(lerp_cyc(anchors, (i + 0.5) / 128)) for i in range(128)]
    for g0, g1 in (EMBER_KEY, BLUE_KEY):
        for i in range(128):
            u = (i + 0.5) / 128
            t = 1 - abs(2 * u - 1)
            pf.append(word((255, g0 + (g1 - g0) * t, 0)))
    return pb, pf


def unhex(s, w):
    return [int(s[i:i + w], 16) for i in range(0, len(s), w)]


def rom(lines, name, typ, n, width, vals, hexw):
    lines.append("    type %s is array (0 to %d) of std_logic_vector(%d downto 0);" % (typ, n - 1, width - 1))
    lines.append("    constant %s : %s := (" % (name, typ))
    per = 8 if hexw <= 8 else 4
    for i in range(0, n, per):
        row = ", ".join('x"%0*x"' % (hexw, vals[j]) for j in range(i, i + per))
        lines.append("        " + row + ("," if i + per < n else ""))
    lines.append("    );")


def main():
    pb, pf = palettes()
    h = unhex(H_HEX, 4)
    v = unhex(V_HEX, 4)
    e = unhex(E_HEX, 2)
    rt = unhex(RT_HEX, 20)
    assert len(h) == 512 and len(v) == 512 and len(e) == 512 and len(rt) == 256
    by, bu, bv = hw(POOL_EMBER)
    cy, cu, cv = hw(POOL_BLUE)
    oy, ou, ov = hw(OUTLINE)
    L = ["-- Generated by bunsen.py: do not edit.  Palettes, field tables, the key / pool row table.",
         "library ieee;", "use ieee.std_logic_1164.all;", "use ieee.numeric_std.all;", "",
         "package bunsen_pkg is",
         "    constant C_BU_FLAME  : integer := %d;" % FLAME,
         "    constant C_BU_BLUE_Y : integer := %d;" % by,
         "    constant C_BU_BLUE_U : integer := %d;" % bu,
         "    constant C_BU_BLUE_V : integer := %d;" % bv,
         "    constant C_BU_POOL2_Y : integer := %d;" % cy,
         "    constant C_BU_POOL2_U : integer := %d;" % cu,
         "    constant C_BU_POOL2_V : integer := %d;" % cv,
         "    constant C_BU_OL_Y   : integer := %d;" % oy,
         "    constant C_BU_OL_U   : integer := %d;" % ou,
         "    constant C_BU_OL_V   : integer := %d;" % ov]
    rom(L, "C_BU_PB", "t_bu_pb", 256, 32, pb, 8)
    rom(L, "C_BU_PF", "t_bu_pf", 256, 32, pf, 8)
    rom(L, "C_BU_H", "t_bu_h", 512, 16, h, 4)
    rom(L, "C_BU_V", "t_bu_v", 512, 16, v, 4)
    rom(L, "C_BU_E", "t_bu_e", 512, 8, e, 2)
    rom(L, "C_BU_RT", "t_bu_rt", 256, 80, rt, 20)
    L.append("end package bunsen_pkg;")
    with open(os.path.join(HERE, "bunsen_pkg.vhd"), "w") as f:
        f.write("\n".join(L) + "\n")
    print("bunsen_pkg.vhd written (PB/PF 256 x 32, H/V 512 x 16, E 512 x 8, RT 256 x 80)")


if __name__ == "__main__":
    main()
